contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        // Before initialization, SetMinSum should not revert on a fresh contract.
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }

        bool setMinSumAfterReverted;
        c.SetMinSum(_val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { setMinSumAfterReverted = true; } else { setMinSumAfterReverted = false; }

        assert(!initReverted && setMinSumAfterReverted);
    }

    receive() external payable {}
}

