// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        bool setMinSumAfterReverted;
        try c.SetMinSum(_val) { setMinSumAfterReverted = false; } catch { setMinSumAfterReverted = true; }
        assertTrue(!initReverted && setMinSumAfterReverted);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
